import{_ as a,o,c as s,a1 as i}from"./chunks/framework.DceXOx8u.js";const h=JSON.parse('{"title":"Solución de problemas","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/es/guide/solucion-problemas"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/es/guide/solucion-problemas"}]]},"headers":[],"relativePath":"es/guide/solucion-problemas.md","filePath":"es/guide/solucion-problemas.md"}'),n={name:"es/guide/solucion-problemas.md"};function t(r,e,d,l,c,p){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h1><p>Los errores más frecuentes, qué significan y cómo resolverlos. Busca en esta página el mensaje exacto que ves (la mayoría de los errores de botmesh nombran la opción o el paquete implicado).</p><h2 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h2><h3 id="err-pnpm-ignored-builds-o-native-module-was-never-built" tabindex="-1"><code>ERR_PNPM_IGNORED_BUILDS</code> o &quot;native module was never built&quot; <a class="header-anchor" href="#err-pnpm-ignored-builds-o-native-module-was-never-built" aria-label="Permalink to &quot;`ERR_PNPM_IGNORED_BUILDS` o &quot;native module was never built&quot;&quot;">​</a></h3><p>pnpm 10 y posteriores no ejecutan los scripts de instalación de las dependencias hasta que decides cuáles pueden correr. pnpm 11 detiene la instalación con <code>ERR_PNPM_IGNORED_BUILDS</code>; pnpm 10 instala sin ellos y el fallo aparece después.</p><p>Decide una vez en <code>pnpm-workspace.yaml</code> (o ejecuta <code>pnpm approve-builds</code>) y reinstala:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allowBuilds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  better-sqlite3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # binario nativo de @botmesh/sqlite-store: debe ejecutarse</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;@whiskeysockets/baileys&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # solo comprueba la versión de Node.js</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  protobufjs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # solo muestra un aviso de versión</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ffmpeg-static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # solo si lo instalaste para las notas de voz de Baileys</span></span></code></pre></div><p>En pnpm 10 el equivalente es <code>onlyBuiltDependencies: [better-sqlite3]</code>. Si <code>better-sqlite3</code> se saltó su script, <code>SQLiteStore</code> lanza <code>better-sqlite3 is installed but its native module was never built</code>. npm ejecuta todos los scripts de instalación, así que no necesita nada de esto.</p><h3 id="el-proceso-aborta-con-assertion-failed-env-nullptr" tabindex="-1">El proceso aborta con <code>Assertion failed: (env) != nullptr</code> <a class="header-anchor" href="#el-proceso-aborta-con-assertion-failed-env-nullptr" aria-label="Permalink to &quot;El proceso aborta con `Assertion failed: (env) != nullptr`&quot;">​</a></h3><p>Usas Node.js 24.19 o posterior con <code>better-sqlite3</code> 11 o 12. Una regresión de Node.js (<a href="https://github.com/nodejs/node/issues/65446" target="_blank" rel="noreferrer">nodejs/node#65446</a>) puede abortar el proceso en <code>RemoveEnvironmentCleanupHook</code> cuando el recolector libera una sentencia preparada. Instala <code>better-sqlite3</code> 13, que usa N-API y no está afectado:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> better-sqlite3@^13</span></span></code></pre></div><h3 id="built-for-another-node-js-version-node-module-version" tabindex="-1">&quot;built for another Node.js version&quot; / <code>NODE_MODULE_VERSION</code> <a class="header-anchor" href="#built-for-another-node-js-version-node-module-version" aria-label="Permalink to &quot;&quot;built for another Node.js version&quot; / `NODE_MODULE_VERSION`&quot;">​</a></h3><p>Un módulo nativo (casi siempre <code>better-sqlite3</code>) se compiló para el Node.js que tenías antes de actualizar. Recompílalo con el Node.js que ejecuta el bot:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebuild</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> better-sqlite3</span></span></code></pre></div><h3 id="err-require-esm-o-require-is-not-defined" tabindex="-1"><code>ERR_REQUIRE_ESM</code> o <code>require is not defined</code> <a class="header-anchor" href="#err-require-esm-o-require-is-not-defined" aria-label="Permalink to &quot;`ERR_REQUIRE_ESM` o `require is not defined`&quot;">​</a></h3><p>botmesh es solo ESM. Usa <code>import</code> y añade <code>&quot;type&quot;: &quot;module&quot;</code> a tu <code>package.json</code> (o usa archivos <code>.mjs</code>). Con TypeScript, configura <code>&quot;module&quot;: &quot;nodenext&quot;</code>.</p><h3 id="pnpm-add-botmesh-core-instala-una-build-anterior" tabindex="-1"><code>pnpm add @botmesh/core</code> instala una build anterior <a class="header-anchor" href="#pnpm-add-botmesh-core-instala-una-build-anterior" aria-label="Permalink to &quot;`pnpm add @botmesh/core` instala una build anterior&quot;">​</a></h3><p>botmesh está en beta: una instalación sin tag instala la beta, y <code>@beta</code> resuelve siempre a la más reciente (<code>latest</code> se mueve a mano tras cada publicación). Justo después de una publicación, una instalación sin tag puede seguir obteniendo la beta anterior hasta que se mueve <code>latest</code>, y un proyecto que mezcla builds puede fallar por exports que faltan o rangos de peers. Revisa los tags con <code>pnpm view @botmesh/core dist-tags</code> e instala la beta más reciente con el tag, por ejemplo <code>pnpm add @botmesh/core@beta @botmesh/baileys@beta</code>. Mira <a href="./inicio">Instalación</a>.</p><h2 id="whatsapp-web-baileys" tabindex="-1">WhatsApp Web (Baileys) <a class="header-anchor" href="#whatsapp-web-baileys" aria-label="Permalink to &quot;WhatsApp Web (Baileys)&quot;">​</a></h2><h3 id="la-conexion-se-cierra-con-428-antes-de-que-aparezca-el-qr" tabindex="-1">La conexión se cierra con <code>428</code> antes de que aparezca el QR <a class="header-anchor" href="#la-conexion-se-cierra-con-428-antes-de-que-aparezca-el-qr" aria-label="Permalink to &quot;La conexión se cierra con `428` antes de que aparezca el QR&quot;">​</a></h3><p>WhatsApp cierra con <code>428 Connection Terminated</code> las conexiones que usan un handshake antiguo. Revisa dos cosas:</p><ol><li>Que <code>@whiskeysockets/baileys</code> resuelva a <code>7.0.0-rc14</code> o posterior en tu lockfile (<code>pnpm why @whiskeysockets/baileys</code>). <code>@botmesh/baileys</code> fija una versión que funciona; un override o un lockfile viejo pueden traer otra anterior.</li><li>Que no pases una tupla <code>browser</code> propia. Deja <code>browser</code> sin definir (o usa un preset como <code>&#39;macOS&#39;</code>): las identidades no estándar pueden recibir <code>428</code>.</li></ol><p>El provider también necesita llegar a <code>wss://web.whatsapp.com</code> y, al arrancar, a <code>raw.githubusercontent.com</code> (para leer la versión actual de WhatsApp Web).</p><h3 id="el-qr-no-aparece" tabindex="-1">El QR no aparece <a class="header-anchor" href="#el-qr-no-aparece" aria-label="Permalink to &quot;El QR no aparece&quot;">​</a></h3><p>Imprímelo en la terminal o guárdalo como PNG, o maneja tú el evento <code>qr</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> provider</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BaileysProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ session: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mi-bot&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, qr: { terminal: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, file: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;./qr.png&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } })</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;qr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">artifact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Escanea o escribe esto:&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, artifact)) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// un QR o un código de emparejamiento</span></span></code></pre></div><p>Para vincular sin QR, pasa <code>pairingPhoneNumber: &#39;+57300…&#39;</code> y escribe el código que llega en el evento <code>qr</code> en WhatsApp → Dispositivos vinculados.</p><h3 id="el-bot-pide-un-qr-nuevo-o-deja-de-reconectar" tabindex="-1">El bot pide un QR nuevo o deja de reconectar <a class="header-anchor" href="#el-bot-pide-un-qr-nuevo-o-deja-de-reconectar" aria-label="Permalink to &quot;El bot pide un QR nuevo o deja de reconectar&quot;">​</a></h3><p>El provider informa el motivo en el evento <code>connection</code>:</p><table tabindex="0"><thead><tr><th><code>reason</code></th><th>Qué pasó</th><th>Qué hacer</th></tr></thead><tbody><tr><td><code>sessionInvalid</code></td><td>Desvinculaste el dispositivo desde el teléfono o los archivos de sesión están dañados. El provider borra la carpeta de esa sesión.</td><td>Escanea el QR nuevo.</td></tr><tr><td><code>sessionTakenOver</code></td><td>Otro proceso usa la misma sesión, o WhatsApp lo prohibió. El provider <strong>no</strong> reconecta, para proteger el número.</td><td>Detén la otra instancia (un deploy viejo, otra terminal) y arranca de nuevo.</td></tr><tr><td><code>transient</code></td><td>Una caída de red. El provider reintenta con backoff (hasta 10 intentos por defecto).</td><td>Nada; ajusta <code>reconnect: { maxAttempts, baseMs, capMs }</code> si hace falta.</td></tr></tbody></table><h3 id="la-misma-persona-aparece-con-dos-ids-o-un-flujo-deja-de-esperar-la-respuesta" tabindex="-1">La misma persona aparece con dos ids, o un flujo deja de esperar la respuesta <a class="header-anchor" href="#la-misma-persona-aparece-con-dos-ids-o-un-flujo-deja-de-esperar-la-respuesta" aria-label="Permalink to &quot;La misma persona aparece con dos ids, o un flujo deja de esperar la respuesta&quot;">​</a></h3><p>WhatsApp identifica a las personas por número de teléfono (<strong>PN</strong>, <code>…@s.whatsapp.net</code>) y por un id opaco (<strong>LID</strong>, <code>…@lid</code>), y la forma puede cambiar entre mensajes. <code>@botmesh/baileys</code> lo resuelve antes de que el bot vea el mensaje: <code>ctx.sender</code> y <code>ctx.from</code> usan el PN cuando se conoce y, si no, el LID; los valores crudos están en <code>ctx.senderInfo.platformData</code> (<code>phoneNumber</code>, <code>lid</code>).</p><ul><li><strong>Nunca guardes datos con claves de <code>ctx.raw</code></strong> (el <code>remoteJid</code> crudo): usa <code>ctx.sender</code> / <code>ctx.from</code>.</li><li><strong>Una persona que solo tiene LID</strong> (usuarios con nombre de usuario de WhatsApp) conserva un id LID estable; <code>platformData.phoneNumber</code> es <code>undefined</code>. No supongas que <code>ctx.sender</code> es un teléfono.</li><li><strong>Si el PN se aprende a mitad de una conversación</strong>, la persona pasa al id PN y una conversación iniciada con el LID deja de recibir sus mensajes. Ponle <code>.timeout()</code> a los flujos (o <code>timeout</code> a <code>c.ask</code>) para que se cierre sola, y guarda <code>platformData.phoneNumber</code> y <code>platformData.lid</code> si mantienes registros por persona.</li><li><strong>Las listas de acceso comparan ids exactos</strong>: añade el id completo (<code>573001234567@s.whatsapp.net</code>, o el id <code>@lid</code>), no un número suelto. Construye ids con <code>toJid(&#39;+57 300 123 4567&#39;)</code>.</li></ul><h3 id="los-envios-fallan-por-rate-limit-o-las-respuestas-tardan" tabindex="-1">Los envíos fallan por rate limit o las respuestas tardan <a class="header-anchor" href="#los-envios-fallan-por-rate-limit-o-las-respuestas-tardan" aria-label="Permalink to &quot;Los envíos fallan por rate limit o las respuestas tardan&quot;">​</a></h3><p>El provider de Baileys encola los envíos en un token bucket (5 por chat cada 10 s y 50 en total por minuto por defecto) para reducir el riesgo de baneo. Un envío que espera más de <code>rateLimit.maxWait</code> (30 s) se rechaza con <code>RateLimitedError</code>. Reparte los envíos masivos con <code>bot.broadcast()</code> (lotes, pausas, reintentos) en lugar de un bucle de <code>bot.send()</code>. Mira <a href="./rate-limiting">Rate limiting</a>.</p><h2 id="whatsapp-cloud-api-messenger-e-instagram" tabindex="-1">WhatsApp Cloud API, Messenger e Instagram <a class="header-anchor" href="#whatsapp-cloud-api-messenger-e-instagram" aria-label="Permalink to &quot;WhatsApp Cloud API, Messenger e Instagram&quot;">​</a></h2><h3 id="la-firma-del-webhook-no-coincide-403" tabindex="-1">La firma del webhook no coincide (403) <a class="header-anchor" href="#la-firma-del-webhook-no-coincide-403" aria-label="Permalink to &quot;La firma del webhook no coincide (403)&quot;">​</a></h3><p>Si todos los webhooks reciben <code>403</code>, falló la comprobación de <code>X-Hub-Signature-256</code>. Meta firma exactamente los bytes que envía, así que:</p><ul><li>Pasa el <strong>body crudo</strong> a <code>provider.ingest(body, headers)</code>: <code>express.raw({ type: &#39;application/json&#39; })</code>, el <code>Buffer</code> que juntas con <code>node:http</code> o el body crudo de tu framework. Un body parseado por <code>express.json()</code> y vuelto a serializar nunca coincide (con <code>appSecret</code>, un objeto ya parseado recibe <code>400</code>).</li><li>Usa el <strong>App Secret</strong> de la app dueña del webhook (Configuración de la app → Básica), no el access token ni el verify token.</li><li>No pongas delante del endpoint un proxy que reescriba el body (compresión, JSON reformateado).</li></ul><p>Solo para pruebas locales, <code>allowUnsignedWebhooks: true</code> desactiva la comprobación.</p><h3 id="meta-no-puede-verificar-la-url-del-webhook" tabindex="-1">Meta no puede verificar la URL del webhook <a class="header-anchor" href="#meta-no-puede-verificar-la-url-del-webhook" aria-label="Permalink to &quot;Meta no puede verificar la URL del webhook&quot;">​</a></h3><p>El handshake <code>GET</code> compara <code>hub.verify_token</code> con el <code>verifyToken</code> del provider. Responde con <code>provider.verifyChallenge(req.query)</code> y con <code>403</code> cuando devuelve <code>null</code>. La URL debe ser HTTPS pública (usa un túnel como <code>cloudflared</code> o <code>ngrok</code> en desarrollo).</p><h3 id="outsidesessionwindowerror" tabindex="-1"><code>OutsideSessionWindowError</code> <a class="header-anchor" href="#outsidesessionwindowerror" aria-label="Permalink to &quot;`OutsideSessionWindowError`&quot;">​</a></h3><p>Pasaron más de 24 horas desde el último mensaje del usuario y Meta solo acepta plantillas aprobadas. Envía un <code>{ kind: &#39;template&#39;, … }</code> o deja que el <code>sessionWindow</code> del provider reabra la conversación por ti. Mira <a href="./ventana-24h">Ventana de 24 h de WhatsApp</a>.</p><h3 id="recipientunreachableerror-con-un-numero-de-prueba" tabindex="-1"><code>RecipientUnreachableError</code> con un número de prueba <a class="header-anchor" href="#recipientunreachableerror-con-un-numero-de-prueba" aria-label="Permalink to &quot;`RecipientUnreachableError` con un número de prueba&quot;">​</a></h3><p>Un número de prueba solo puede escribir a los números de la lista &quot;Para&quot; de la configuración de la API en el panel de Meta (código Graph <code>131030</code>). Añade ahí el destinatario.</p><h3 id="the-access-token-is-invalid-or-expired-check-the-configured-phone-number-id" tabindex="-1">&quot;the access token is invalid or expired&quot; / &quot;check the configured phone number id&quot; <a class="header-anchor" href="#the-access-token-is-invalid-or-expired-check-the-configured-phone-number-id" aria-label="Permalink to &quot;&quot;the access token is invalid or expired&quot; / &quot;check the configured phone number id&quot;&quot;">​</a></h3><p>El código Graph <code>190</code> es un access token inválido o caducado: usa un token permanente de usuario del sistema con <code>whatsapp_business_messaging</code>. El código <code>100</code>/<code>33</code> indica que el <code>phoneNumberId</code> no existe o que el token no tiene acceso: copia el <strong>id del número de teléfono</strong> de la configuración de la API (no es el número).</p><h3 id="rate-limits-130429-131056-80007" tabindex="-1">Rate limits (<code>130429</code>, <code>131056</code>, <code>80007</code>…) <a class="header-anchor" href="#rate-limits-130429-131056-80007" aria-label="Permalink to &quot;Rate limits (`130429`, `131056`, `80007`…)&quot;">​</a></h3><p>Llegan como <code>RateLimitedError</code> con <code>retryAfterMs</code>. Una espera corta en un envío de <code>ctx</code> se reintenta una vez (<code>BotConfig.rateLimitRetry</code>), y <code>bot.broadcast()</code> reintenta por chat (<code>retries</code>, 3 por defecto). Para tráfico masivo, baja <code>concurrency</code> y añade <code>delayBetween</code>.</p><h2 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h2><h3 id="_409-conflict-y-el-bot-deja-de-recibir-updates" tabindex="-1"><code>409 Conflict</code> y el bot deja de recibir updates <a class="header-anchor" href="#_409-conflict-y-el-bot-deja-de-recibir-updates" aria-label="Permalink to &quot;`409 Conflict` y el bot deja de recibir updates&quot;">​</a></h3><p>Dos procesos hacen polling con el mismo token (o hay un webhook configurado mientras haces polling). El provider se detiene a propósito (<code>sessionTakenOver</code>). Detén la otra instancia, o borra el webhook con <code>deleteWebhook</code> antes de usar long polling.</p><h3 id="check-the-bot-token-and-baseurl-404" tabindex="-1">&quot;check the bot token and baseUrl&quot; (404) <a class="header-anchor" href="#check-the-bot-token-and-baseurl-404" aria-label="Permalink to &quot;&quot;check the bot token and baseUrl&quot; (404)&quot;">​</a></h3><p>El token está mal formado (cópialo de nuevo desde @BotFather) o <code>baseUrl</code> apunta a una ruta equivocada.</p><h3 id="el-webhook-responde-401" tabindex="-1">El webhook responde <code>401</code> <a class="header-anchor" href="#el-webhook-responde-401" aria-label="Permalink to &quot;El webhook responde `401`&quot;">​</a></h3><p>La cabecera <code>X-Telegram-Bot-Api-Secret-Token</code> no coincide con <code>webhookSecret</code>. Pasa el mismo valor como <code>secret_token</code> a <code>setWebhook</code>.</p><h2 id="el-bot" tabindex="-1">El bot <a class="header-anchor" href="#el-bot" aria-label="Permalink to &quot;El bot&quot;">​</a></h2><h3 id="botnotrunningerror-bot-is-not-running" tabindex="-1"><code>BotNotRunningError: bot is not running</code> <a class="header-anchor" href="#botnotrunningerror-bot-is-not-running" aria-label="Permalink to &quot;`BotNotRunningError: bot is not running`&quot;">​</a></h3><p>Enviaste, editaste o borraste un mensaje antes de <code>await bot.start()</code> o después de <code>bot.stop()</code>. Programa los envíos proactivos desde <code>bot.on(&#39;ready&#39;, …)</code> o después de que <code>start()</code> resuelva.</p><h3 id="configvalidationerror-invalid-config-opcion" tabindex="-1"><code>ConfigValidationError: Invalid config.&lt;opción&gt;</code> <a class="header-anchor" href="#configvalidationerror-invalid-config-opcion" aria-label="Permalink to &quot;`ConfigValidationError: Invalid config.&lt;opción&gt;`&quot;">​</a></h3><p>Una opción de <code>new Bot()</code> tiene un tipo incorrecto o una duración inválida. El mensaje nombra la opción (<code>err.field</code>); las duraciones aceptan un string (<code>&#39;30s&#39;</code>, <code>&#39;5m&#39;</code>) o milisegundos.</p><h3 id="plugin-nombre-is-already-plugged-on-this-bot" tabindex="-1"><code>Plugin &quot;&lt;nombre&gt;&quot; is already plugged on this bot</code> <a class="header-anchor" href="#plugin-nombre-is-already-plugged-on-this-bot" aria-label="Permalink to &quot;`Plugin &quot;&lt;nombre&gt;&quot; is already plugged on this bot`&quot;">​</a></h3><p>Cada nombre de plugin se puede enchufar una vez. Desenchúfalo primero con la función que devolvió <code>bot.plug()</code>, o pon <code>multiple: true</code> en el spec de cada instancia.</p><h3 id="bot-when-hola-no-coincide-con-hola-a-todos" tabindex="-1"><code>bot.when(&#39;hola&#39;)</code> no coincide con &quot;hola a todos&quot; <a class="header-anchor" href="#bot-when-hola-no-coincide-con-hola-a-todos" aria-label="Permalink to &quot;`bot.when(&#39;hola&#39;)` no coincide con &quot;hola a todos&quot;&quot;">​</a></h3><p>Los triggers de texto comparan por <strong>igualdad normalizada</strong> (se ignoran mayúsculas, tildes y espacios de más), no por &quot;contiene&quot;. Usa <code>{ pattern: &#39;hola&#39;, match: &#39;contains&#39; }</code> o una <code>RegExp</code>. Mira <a href="./triggers">Triggers especiales</a>.</p><h3 id="el-bot-no-responde-en-grupos" tabindex="-1">El bot no responde en grupos <a class="header-anchor" href="#el-bot-no-responde-en-grupos" aria-label="Permalink to &quot;El bot no responde en grupos&quot;">​</a></h3><p>Revisa <code>groupMode</code> (<code>&#39;mentions&#39;</code> y <code>&#39;commands&#39;</code> limitan lo que el bot responde en grupos) y el <code>scope</code> del trigger. En grupos, las conversaciones son por participante por defecto.</p><h3 id="los-textos-integrados-salen-en-ingles" tabindex="-1">Los textos integrados salen en inglés <a class="header-anchor" href="#los-textos-integrados-salen-en-ingles" aria-label="Permalink to &quot;Los textos integrados salen en inglés&quot;">​</a></h3><p>Los textos de timeouts, reintentos, comandos slash y formularios están en inglés por defecto. Usa <code>new Bot({ lang: &#39;es&#39; })</code> para tenerlos en español, o registra los tuyos con <code>bot.locale()</code>. Mira <a href="./i18n">Internacionalización</a>.</p><h3 id="un-flujo-persistent-olvida-donde-estaba-tras-reiniciar" tabindex="-1">Un flujo <code>.persistent()</code> olvida dónde estaba tras reiniciar <a class="header-anchor" href="#un-flujo-persistent-olvida-donde-estaba-tras-reiniciar" aria-label="Permalink to &quot;Un flujo `.persistent()` olvida dónde estaba tras reiniciar&quot;">​</a></h3><p>El <code>MemoryStore</code> por defecto vive en RAM. Usa un store durable (<code>@botmesh/sqlite-store</code>, <code>@botmesh/redis-store</code> o <code>new MemoryStore({ file })</code>). Mira <a href="./store">Store persistente</a>.</p><h2 id="¿sigues-atascado" tabindex="-1">¿Sigues atascado? <a class="header-anchor" href="#¿sigues-atascado" aria-label="Permalink to &quot;¿Sigues atascado?&quot;">​</a></h2><ul><li>Activa los logs de depuración: <code>new Bot({ provider, logger: pino({ level: &#39;debug&#39; }) })</code>. Los ids de chat y remitente salen hasheados en los logs del bot por defecto (<code>logIds</code>).</li><li>Revisa las <a href="./faq">preguntas frecuentes</a> y el README del paquete de tu canal.</li><li><a href="https://github.com/andresayac/botmesh/issues" target="_blank" rel="noreferrer">Abre un issue</a> con el mensaje de error, las versiones de los paquetes (<code>pnpm ls @botmesh/*</code>) y tu versión de Node.js. Nunca pegues tokens ni archivos de sesión.</li></ul>',74)])])}const b=a(n,[["render",t]]);export{h as __pageData,b as default};
